		_, templ_7745c5c3_Err = templ_7745c5c3_Buffer.WriteString("<p>Dobar tijek rada mora objasniti i što se događa kad nešto nedostaje. Ako je upit nepotpun, sustav ga ne bi trebao tiho odbaciti niti nadopuniti nagađanjem. Označi iznimku, sačuva ulazne podatke i preda odluku osobi.</p>")
